// Remove the 73 hand-written potion entries that the sapling merge resurrected in src/blocks.js.
// Every one is also generated by src/extraPotions.js (proven by inspect-potion-block.mjs), and keeping
// both trips the collision guard at the bottom of blocks.js.
//
// The span is located structurally rather than by hard-coded line numbers, and the script refuses if
// anything inside it is not a potion entry or is not generated.
import { readFileSync, writeFileSync } from 'node:fs';

const ROOT = (process.argv[2] ?? '.').replace(/\\/g, '/').replace(/\/$/, '');
const PATH = `${ROOT}/src/blocks.js`;
const { POTION_ITEMS } = await import(`file:///${ROOT}/src/extraPotions.js`);

const lines = readFileSync(PATH, 'utf8').split(/\r?\n/);

const start = lines.findIndex((l) => /^\s+awkward_potion:/.test(l));
if (start < 0) { console.log('nothing to remove'); process.exit(0); }

const isPotionEntry = (l) => /^\s+[a-z0-9_]*(potion|bottle)[a-z0-9_]*:\s*\{/.test(l);
let end = start;
while (end < lines.length && (isPotionEntry(lines[end]) || lines[end].trim() === '')) end++;

const span = lines.slice(start, end);
const bad = span.filter((l) => l.trim() && !isPotionEntry(l));
if (bad.length) { console.error('refusing: non-potion lines in span'); process.exit(1); }

const names = span.map((l) => l.trim().match(/^([a-z0-9_]+):/)?.[1]).filter(Boolean);
const notGenerated = names.filter((n) => !(n in POTION_ITEMS));
if (notGenerated.length) { console.error('refusing: not generated ->', notGenerated.join(', ')); process.exit(1); }

// Drop the span, and the blank line that preceded it if that leaves two blanks together.
const before = lines.slice(0, start);
const after = lines.slice(end);
const out = [...before, ...after];
writeFileSync(PATH, out.join('\n'), 'utf8');
console.log(`removed ${names.length} duplicated potion entries (lines ${start + 1}..${end})`);
